# מרכיב את 6 הספרים לקובצי נתונים + manifest להתקנה
import pickle,json,hashlib,re
OUT='/home/claude/content/out9/'
W=lambda ch,it: {"group":"","sections":"חלקים","section":"חלק","chapters":ch[0],"chapterOne":ch[1],"items":it[0],"item":it[1],"next":ch[2],"prev":ch[3]}
