BUY='📞 לרכישת הספר המודפס: הרב אברהם ידידיה · 052-766-7806'
B=[
 dict(vi=141,f='mesh',title='משלים קטנים עם מסרים גדולים',nq='מְשָׁלִים קְטַנִּים עִם מְסָרִים גְּדוֹלִים',author='הָרַב אַבְרָהָם יְדִידְיָה',tag='מִתּוֹרָתוֹ שֶׁל רַבִּי נַחְמָן מִבְּרֶסְלֶב זי"ע',
      w=W(("משלים","משל אחד","המשל הבא","המשל הקודם"),("קטעים","קטע")),bg='dawn',art='etzot',
      about=['משלים קטנים עם מסרים גדולים<br>מתורתו של רבי נחמן מברסלב זי"ע','כתיבה ועריכה: אברהם ידידיה<br>מו"ל: \'יְדִידוּת נַפְשִׁי\'<br>מהדורה א\': ירושלים תשפ"ה'],buy=BUY),
 dict(vi=142,f='shem',title='כולנו יודעי שמך',nq='כֻּלָּנוּ יוֹדְעֵי שְׁמֶךָ',author='הָרַב אַבְרָהָם יְדִידְיָה',tag='לְהַכִּיר וְלָדַעַת אֶת הַשֵּׁמוֹת הַקְּדוֹשִׁים בְּשָׂפָה קַלָּה הַשָּׁוָה לְכָל נֶפֶשׁ',
      w=W(("נושאים","נושא אחד","הנושא הבא","הנושא הקודם"),("קטעים","קטע")),bg='stars',art='stars',
      about=['כולנו יודעי שמך<br>להכיר ולדעת את השמות הקדושים בשפה קלה השוה לכל נפש','מו"ל: הוצאת ספרים ידִידוּת נפשי'],buy=BUY),
 dict(vi=143,f='olam',title='עולם חדש',nq='עוֹלָם חָדָשׁ',author='שִׂיחוֹת הָרַב אָשֵׁר עַבָּאדִי שליט"א · עֲרִיכָה: אַבְרָהָם יְדִידְיָה',tag='לְהַכִּיר עוֹלָמוֹת חֲדָשִׁים בְּתוֹרַת רַבִּי נַחְמָן מִבְּרֶסְלֶב',
      w=W(*PER),bg='dawn',art='etzot',
      about=['עולם חדש<br>להכיר עולמות חדשים בתורת רבי נחמן מברסלב<br>שיחות הרב אשר עבאדי<br>מהדורה חדשה ומורחבת','עריכה: אברהם ידידיה<br>מו"ל: עמותת "עטרת מנשה" ע.ר.']),
 dict(vi=144,f='lev',title='דרכי ראיית הלב',nq='דַּרְכֵי רְאִיַּת הַלֵּב',author='הצב"י יָאִיר יְחֶזְקֵאל בַּר-כּוֹכְבָא',tag='קוּנְטְרֵס',w=W(*PER),bg='forest',art='etzot',
      about=['קונטרס<br>דרכי ראיית הלב<br>חיברתיו בחסד ה\' עלי<br>הצב"י יאיר יחזקאל בר-כוכבא']),
 dict(vi=145,f='einei',title='עיני השם',nq='עֵינֵי הַשֵּׁם',author='הצב"י יָאִיר יְחֶזְקֵאל בַּר כּוֹכְבָא',tag='"הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ" (זכריה ד, י)',w=W(*PER),bg='stars',art='stars',
      about=['קונטרס<br>עיני השם<br>"הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ" (זכריה ד,י)','ובו מלוקטים מרגליות יקרות, ממעמקי ים החכמה, של רבותינו הקדושים אשר מפיהם אנו חיים. בעניין ציור השכל וראיית המחשבה, עם הרגשת הלב, של האיש הישראלי ורוח הקודש המפעמת בקרבו, גם ובפרט, בדורנו זה, דור עקבתא דמשיחא.','מנאי הצב"י יאיר יחזקאל בר כוכבא יצ"ו<br>תלמיד לכבוד קדושת, הרועה הנאמן, עטרת ראשינו, אדונינו מורינו ורבינו<br>רבי אשר עבאדי שליט"א<br>המשקה מן המעיין, של הנחל נובע מקור חכמה, רבינו הקדוש, מוהר"ן זי"ע.']),
 dict(vi=146,f='orach',title='אורח צדיקים',nq='אֹרַח צַדִּיקִים',author='אַדְמוֹ"ר הָרַב אָשֵׁר עַבָּאדִי שליט"א',tag='הוּא דֶּרֶךְ סְלוּלָה · בְּדֶרֶךְ מוֹהֲרַ"ן מִבְּרֶסְלֶב',w=W(*PER),bg='dawn',art='etzot',
      about=['קונטרס<br>אורח צדיקים<br>הוא דרך סלולה<br>מאת אדמו"ר הרב אשר עבאדי שליט"א<br>בדרך מוהר"ן מברסלב זצוקלל"ה','"וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם" (משלי ד, יח)','ועמו מראה מקומות מרבנו ז"ל ועוד בשם<br>אורח לצדיק<br>"אֹרַח לַצַּדִּיק מֵישָׁרִים" (ישעיהו כו, ז)']),
]
man=[]
for k,b in enumerate(B):
    bk=pickle.load(open(b['f']+'.book','rb'))
    ab=dict(t='על הספר',i=[dict(n='',b=[['p',x]]) for x in b['about']])
    if b.get('buy'): ab['i'].append(dict(n='',b=[['ins',b['buy']]]))
    bk[0]['c'].insert(0,ab)
    # ניקוי: רווחים כפולים, רווח לפני פיסוק
    for s in bk:
        for c in s['c']:
            for it in c['i']:
                for bl in it['b']: bl[1]=re.sub(r' +([,.:;!?])',r'\1',re.sub(r'\s+',' ',bl[1])).strip()
            c['i']=[it for it in c['i'] if any(bl[1] for bl in it['b'])]
    data=json.dumps(bk,ensure_ascii=False,separators=(',',':'))
    fn='b%d_V%d.%s.json'%(139+k,b['vi'],hashlib.md5(data.encode()).hexdigest()[:10])
    open(OUT+fn,'w',encoding='utf-8').write(data)
    cfg={"title":b['title'],"titleNiqud":b['nq'],"author":b['author'],"tag":b['tag'],"pre2":"","heroSize":34 if len(b['title'])>14 else 40,"bg":b['bg'],"heroArt":b['art'],"planWord":b['w']['items'],"cat":"kuntres","words":b['w']}
    man.append(dict(vi=b['vi'],cfg=cfg,file=fn))
    n=sum(len(c['i']) for s in bk for c in s['c']); w=sum(len(re.sub(r'<[^>]+>',' ',bl[1]).split()) for s in bk for c in s['c'] for it in c['i'] for bl in it['b'])
    print(b['vi'],b['title'],'| sections',len(bk),'chapters',sum(len(s['c']) for s in bk),'items',n,'words',w,'| %dKB'%(len(data.encode())//1024),fn)
json.dump(man,open(OUT+'manifest_pdf.json','w',encoding='utf-8'),ensure_ascii=False)
